import{_ as t,c as p,o as s,ah as o,ao as i,ap as a}from"./chunks/framework.Dq2_gudl.js";const v=JSON.parse('{"title":"允許自己悲傷——你的眼淚，祂都收在瓶子裡","description":"為寵物離世而哭，不是信心不足。詩篇說神把我們的眼淚收在瓶子裡，記在冊上。","frontmatter":{"title":"允許自己悲傷——你的眼淚，祂都收在瓶子裡","description":"為寵物離世而哭，不是信心不足。詩篇說神把我們的眼淚收在瓶子裡，記在冊上。"},"headers":[],"relativePath":"pets-in-heaven/permission-to-grieve.md","filePath":"pets-in-heaven/permission-to-grieve.md"}'),n={name:"pets-in-heaven/permission-to-grieve.md"};function l(c,e,r,h,m,d){return s(),p("div",null,[...e[0]||(e[0]=[o('<div class="pl-quote"><p>「都過了幾個月了，我還在哭。是不是我不夠堅強？是不是我信心太小？」</p><p class="pl-quote-soft">聖經從來沒有把眼淚當成失敗的證據。剛好相反。</p></div><section class="pl-section"><h2>一、神把眼淚收在瓶子裡</h2><blockquote><p><strong>詩篇 56:8</strong></p><p>&quot;Thou tellest my wanderings: put thou my tears into thy bottle: are they not in thy book?&quot;</p></blockquote><p>大衛在極深的痛苦裡寫下這句話。他求神把他的眼淚裝在瓶子裡，記在冊上——在古代，瓶子裡的淚是極珍貴的收藏，是「這個人為這件事哭過」的憑據。</p><p>這意味著：<strong>你的眼淚不是流掉就消失的東西。</strong>沒有一滴被浪費。為牠流的每一滴，神都收著、都記著。</p><p>當你覺得「我是不是哭太多了」，請記得：在神那裡，那不是雜訊，那是紀錄。</p></section><section class="pl-section"><h2>二、神靠近傷心的人，而不是責備他們</h2><blockquote><p><strong>詩篇 34:18</strong></p><p>&quot;The LORD is nigh unto them that are of a broken heart; and saveth such as be of a contrite spirit.&quot;</p></blockquote><blockquote><p><strong>詩篇 147:3</strong></p><p>&quot;He healeth the broken in heart, and bindeth up their wounds.&quot;</p></blockquote><p>注意動詞：祂<em>靠近</em>、祂<em>醫治</em>、祂<em>纏裹</em>。神對傷心的人所做的第一件事，不是要求他振作，而是走過去。</p><p>耶穌也說過一句很短的話：</p><blockquote><p><strong>馬太福音 5:4</strong></p><p>&quot;Blessed are they that mourn: for they shall be comforted.&quot;</p></blockquote><p>「哀慟的人有福了。」悲傷的人不是被責備，而是被宣告有福——因為安慰會來。不是「你應該高興起來」，而是「你會得安慰」。</p></section><section class="pl-section"><h2>三、悲傷不是愛的反面，是愛還在繼續</h2><p>我們不會為不曾愛過的東西哭。你今天會這麼痛，正是因為你們之間真的有過愛。</p><p>神造我們，本來就是會為失去而哭泣的存在。耶穌自己在拉撒路的墳前也哭了（約翰福音 11:35）——祂明知幾分鐘後就要叫他從死裡復活，祂還是哭了。</p><p>所以你不必為眼淚感到抱歉。你不是信心不夠，你只是在愛裡受了傷。</p><p class="pl-quote-soft">如果你願意，可以這樣禱告：</p></section><div class="pl-quote"><p>「主啊，祢知道我哭了多少次。<br>謝謝祢沒有催我快點好起來，反而把每一滴眼淚收在瓶子裡。<br>求祢靠近我，如同祢靠近每一個心碎的人；<br>求祢醫治我，也替我照顧我想念的那一個。<br>今天我不想變強，只想被祢抱住。阿們。」</p></div><section class="pl-section"><h2>四件現在可以為自己做的事</h2><div class="pl-moment-grid"><div class="pl-moment"><span class="pl-moment-icon">🌊</span><h3>不要在情緒最強時做決定</h3><p>悲傷的浪會過去。在最痛的那一刻，只要活過那五分鐘就夠了——不要處理任何事情。</p></div><div class="pl-moment"><span class="pl-moment-icon">🍽️</span><h3>先照顧身體</h3><p>喝水、吃點東西、睡一下。哀傷會消耗身體，而身體餓的時候，心會更痛。</p></div><div class="pl-moment"><span class="pl-moment-icon">📝</span><h3>把牠寫進一本筆記</h3><p>不必寫得漂亮。寫下一個細節：牠怎麼叫你起床、你最喜歡牠哪個表情。讓想念有地方放。</p></div><div class="pl-moment"><span class="pl-moment-icon">🤝</span><h3>找一個真的懂的人</h3><p>不是每個人都懂為動物哭，但有些人懂。如果找不到，寫下來也可以——神讀得到。</p></div></div></section><section class="pl-section"><h2>那一天會來</h2><p>啟示錄應許，有一天神要親自擦去我們一切的眼淚，不再有死亡、悲哀、哭號、疼痛（啟示錄 21:4）。那一天，你會發現你為牠流的每一滴眼淚，都被那位良善的神記得、也被那位良善的神回應。</p><p>在那之前，允許自己悲傷。那是你還能愛牠的方式。</p><p><a href="/pets-in-heaven/">← 回到 Pets in Heaven</a> ｜ 回到第一篇：<a href="/pets-in-heaven/will-i-see-my-pet-again">牠會在那裡嗎？</a></p></section><div class="pl-cta"><h2>今天，只要寫一句話就好。</h2><p>PetLoss 裡有引導式日記與 SOS 陪伴，在你最沉重的時刻給你落地的話語。無需帳號、不上傳、完全離線。</p><a class="pl-download" href="https://apps.apple.com/us/app/petloss-memorial-healing/id6757967412">在 App Store 下載</a></div><div class="pl-bible"><h3>讓聖經的話繼續陪你</h3><p>本文引用的經文都出自聖經。用《彩虹聖經》隨時閱讀神的話、設定每日經文小工具，在想念牠的日子裡仍有一盞燈。</p><div class="pl-bible-shots"><figure><img src="'+i+'" alt="Rainbow Bible 聖經小工具顯示 2 Timothy 2:13" loading="lazy"><figcaption>每日經文放在主畫面</figcaption></figure><figure><img src="'+a+'" alt="Rainbow Bible App 的「天堂裡的毛孩」主題，顯示 Matthew 10:29-31" loading="lazy"><figcaption>切換到「天堂裡的毛孩」主題讀經</figcaption></figure></div><a class="pl-bible-download" href="https://apps.apple.com/app/id6756217525">在 App Store 取得《彩虹聖經》</a></div>',9)])])}const g=t(n,[["render",l]]);export{v as __pageData,g as default};
